<?php
declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';
use App\Security\Csrf;use App\Services\Auth;use App\Services\FinanceService;
Auth::requirePermission('PAYMENT_VIEW_FINANCE');$uid=(int)Auth::user()['id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid token.');$a=$_POST['action']??'';if($a==='create_payment')FinanceService::createPayment((int)$_POST['shipment_id'],(float)$_POST['amount'],strtoupper((string)$_POST['currency']),(string)$_POST['due_at'],$uid);elseif($a==='review_payment')FinanceService::reviewPayment((int)$_POST['payment_id'],(string)$_POST['decision'],(float)($_POST['received_amount']??0),(string)($_POST['notes']??''),$uid);elseif($a==='create_settlement')FinanceService::createSettlement((int)$_POST['payment_id'],(float)$_POST['gross_amount'],(float)$_POST['deduction_amount'],(string)$_POST['due_at'],(string)($_POST['notes']??''),$uid);elseif($a==='settlement_action')FinanceService::settlementAction((int)$_POST['settlement_id'],(string)$_POST['to'],(string)($_POST['method']??''),(string)($_POST['reference']??''),(string)($_POST['notes']??''),$uid);else throw new RuntimeException('Invalid action.');header('Location: ?updated=1');exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}
$eligible=FinanceService::eligible();$rows=FinanceService::all();$pageTitle='Payments & Settlements';require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><h1>Payments & settlements</h1><p>Customer payment records, confirmation, carrier settlement and payout audit.</p></div><span class="badge">Phase 11</span></div>
<?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<div class="card"><h2>Delivered shipments awaiting payment request</h2><?php foreach($eligible as$x):?><form method="post" class="form-grid" style="margin-bottom:12px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="create_payment"><input type="hidden" name="shipment_id" value="<?=h($x['shipment_id'])?>"><div><strong><?=h($x['shipment_ref'].' · '.$x['load_ref'])?></strong><br><span class="muted"><?=h($x['display_name'])?></span></div><div class="field"><label>Amount</label><input type="number" step="0.01" min="0.01" name="amount" value="<?=h($x['offered_amount_tzs']??'')?>" required></div><div class="field"><label>Currency</label><input name="currency" value="TZS" maxlength="3" required></div><div class="field"><label>Due</label><input type="datetime-local" name="due_at" value="<?=h(date('Y-m-d\TH:i',strtotime('+7 days')))?>" required></div><div><button class="button">Create request</button></div></form><?php endforeach;?><?php if(!$eligible):?><p class="muted">None.</p><?php endif;?></div>
<?php foreach($rows as$r):?><div class="card" style="margin-top:18px"><h2><?=h($r['payment_ref'].' · '.$r['shipment_ref'])?></h2><p><?=h($r['payer_name'].' · '.$r['currency'].' '.number_format((float)$r['requested_amount'],2).' · '.$r['payment_status'])?></p><p class="muted">Reference: <?=h($r['transaction_reference']?:'—')?> · Received: <?=h(number_format((float)$r['received_amount'],2))?></p>
<?php if($r['payment_status']==='submitted'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="review_payment"><input type="hidden" name="payment_id" value="<?=h($r['payment_id'])?>"><div class="form-grid"><div class="field"><label>Confirmed amount</label><input type="number" step="0.01" min="0" name="received_amount" value="<?=h($r['received_amount'])?>"></div><div class="field"><label>Review notes</label><input name="notes" maxlength="1000"></div></div><button class="button" name="decision" value="confirmed">Confirm payment</button> <button class="button" name="decision" value="rejected">Reject</button></form><?php endif;?>
<?php if($r['payment_status']==='confirmed'&&!$r['settlement_id']):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="create_settlement"><input type="hidden" name="payment_id" value="<?=h($r['payment_id'])?>"><h3>Create carrier settlement</h3><div class="form-grid"><div class="field"><label>Gross</label><input type="number" step="0.01" min="0.01" name="gross_amount" value="<?=h($r['offered_amount_tzs']?:$r['received_amount'])?>" required></div><div class="field"><label>Deductions</label><input type="number" step="0.01" min="0" name="deduction_amount" value="0" required></div><div class="field"><label>Due</label><input type="datetime-local" name="due_at" value="<?=h(date('Y-m-d\TH:i',strtotime('+3 days')))?>" required></div><div class="field"><label>Notes</label><input name="notes" maxlength="1000"></div></div><button class="button">Create settlement</button></form><?php endif;?>
<?php if($r['settlement_id']):?><hr><h3><?=h($r['settlement_ref'].' · '.$r['carrier_name'].' · '.$r['settlement_status'])?></h3><p><?=h('Gross '.$r['gross_amount'].' − deductions '.$r['deduction_amount'].' = net '.$r['net_amount'].' '.$r['currency'])?></p>
<?php if($r['settlement_status']==='draft'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="settlement_action"><input type="hidden" name="settlement_id" value="<?=h($r['settlement_id'])?>"><input type="hidden" name="to" value="approved"><button class="button">Approve settlement</button></form><?php elseif($r['settlement_status']==='approved'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="settlement_action"><input type="hidden" name="settlement_id" value="<?=h($r['settlement_id'])?>"><input type="hidden" name="to" value="paid"><div class="form-grid"><div class="field"><label>Payout method</label><select name="method"><option value="bank_transfer">Bank transfer</option><option value="mobile_money">Mobile money</option><option value="cash">Cash</option><option value="other">Other</option></select></div><div class="field"><label>Transaction reference</label><input name="reference" required></div><div class="field"><label>Notes</label><input name="notes"></div></div><button class="button">Record payout</button></form><?php else:?><p>Payout: <?=h($r['payout_status'].' · '.$r['payout_reference'])?></p><?php endif;?><?php endif;?></div><?php endforeach;?>
<?php require BASE_PATH.'/app/Views/layout/footer.php';?>